fn flipud(m: Vec<f32>) -> Vec<f32> {
    // `into_iter()` consumes `m`, yielding its elements by value.
    // `rev()` reverses the iterator.
    // `collect()` gathers the values into a new Vec<f32>.
    m.into_iter().rev().collect()
}

